window.RP_SESSION={"id":"S-718c66f96c8f","messages":[{"id":"RP-III-0084426","time":"2026-04-26T19:25:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084427","time":"2026-04-26T19:26:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"장례식장의 분위기가 무거워서 일찍이 빠져나왔다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084428","time":"2026-04-26T19:27:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"가족을 잃는다는 것은, 영영 익숙해지지 않을 것 같다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084429","time":"2026-04-26T19:28:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그렇기에 딘의 마음을 모르는 것은 아니지만.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084430","time":"2026-04-26T19:30:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"죽음을 제대로 존중해주는 것이야 말로 그를 위한 것이라고 생각했다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084431","time":"2026-04-26T19:30:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"아니면, 그를 살리려고 추악하게 발악하고 싶지 않은 나의 가식일 수도.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084432","time":"2026-04-26T19:31:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그렇다면 다른 언데드들은, 존재만으로 죽음을 모욕하는 존재들인건가?","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084433","time":"2026-04-26T19:32:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그의 미약한 지식으로는 정답을 알 수 없었다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084434","time":"2026-04-26T19:32:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그의 나약한 마음으로는 행보를 정할 수 없었다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084435","time":"2026-04-26T19:33:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"그저 울렁이는 가슴 속을 마음껏 헤엄치다가.\n\n어디론가 떠밀려 도착하기를 기다리며 눈을 감았다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0084436","time":"2026-04-26T19:42:00+09:00","room":"RP III","name":"시안","profile":"스노우 글로우","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n자칫, 고인모독이 될거같다는 생각을, 남들도 하지않았을리가 없다 생각하여. 말을삼켰습니다.\n\n아직 살아있는 동료를 최대한 살리려는것과, 이미 죽은 동료를 법칙을 거슬려서라도 살리는건. 너무 다른이야기니까요.","characters":["P-77d4478f4f51"]}]};
